/*
 * Text as Python's str sees it, for core/rb_build.c, which must write the
 * same stations.txt as tools/rb_to_stations.py: strings of code points
 * with Python's isspace/isalnum/isdigit, lower() (with the final sigma
 * rule), split/strip on Unicode whitespace, and the script's fold() (NFKD
 * without combining marks, lower case, single spaces).
 *
 * The tables (core/unitab.c) are generated by tools/make_unicode_tables.py.
 */
#ifndef DXG_USTR_H
#define DXG_USTR_H

#include <stddef.h>
#include <stdint.h>

typedef struct {
    uint32_t *c;
    size_t n, cap;
} ustr;

/* Generated tables. */
typedef struct {
    uint32_t first, last;
    unsigned char flags;
} unitab_range;
typedef struct {
    uint32_t cp;
    uint32_t off;  /* into UNITAB_POOL */
    unsigned char n;
} unitab_map;
enum {
    U_SPACE = 1, U_ALNUM = 2, U_DIGIT = 4, U_CC = 8, U_CFZ = 16, U_CASED = 32, U_IGNORABLE = 64
};
extern const char UNITAB_VERSION[];
extern const unitab_range UNITAB_FLAGS[];
extern const size_t UNITAB_FLAGS_N;
extern const uint32_t UNITAB_POOL[];
extern const unitab_map UNITAB_LOWER[], UNITAB_FOLD[];
extern const size_t UNITAB_LOWER_N, UNITAB_FOLD_N;

unsigned u_flags(uint32_t cp);
#define u_isspace(cp) ((u_flags(cp) & U_SPACE) != 0)
#define u_isalnum(cp) ((u_flags(cp) & U_ALNUM) != 0)
#define u_isdigit(cp) ((u_flags(cp) & U_DIGIT) != 0)

void ustr_init(ustr *s);
void ustr_free(ustr *s);
void ustr_clear(ustr *s);
void ustr_push(ustr *s, uint32_t cp);
void ustr_append(ustr *s, const ustr *t);
void ustr_append_ascii(ustr *s, const char *a);
/* Decodes UTF-8 (invalid bytes become U+FFFD). Replaces the contents. */
void ustr_set_utf8(ustr *s, const char *p, size_t n);
/* As UTF-8, malloc'd (NULL if out of memory). */
char *ustr_utf8(const ustr *s);
/* Appends the UTF-8 to a growing buffer. */
void ustr_copy(ustr *dst, const ustr *src);

/* str.strip() / rstrip() / lstrip(chars) for one ASCII char. */
void ustr_strip(ustr *s);
void ustr_rstrip(ustr *s);
void ustr_lstrip_char(ustr *s, uint32_t ch);
void ustr_rstrip_chars(ustr *s, const char *chars);
/* " ".join(s.split()) */
void ustr_collapse_spaces(ustr *s);
/* s = s[:n] */
void ustr_truncate(ustr *s, size_t n);
/* s.lower() and s.upper() (upper: ASCII only, enough for codecs and codes). */
void ustr_lower(ustr *s);
void ustr_upper_ascii(ustr *s);
/* The script's fold(): lower case without accents, single spaces. */
void ustr_fold(ustr *s);
int ustr_eq(const ustr *a, const ustr *b);
int ustr_eq_ascii(const ustr *a, const char *b);
/* Index of t in s from `from`, or -1. */
long ustr_find(const ustr *s, const ustr *t, size_t from);
long ustr_find_ascii(const ustr *s, const char *t);
int ustr_starts_ascii(const ustr *s, const char *prefix);

#endif
